import java.util.*;

class Solution {
    public List<List<String>> peacefulQueens(int n) {
        List<List<String>> out = new ArrayList<>();
        place(0, n, new int[n], new boolean[n], new boolean[2 * n], new boolean[2 * n], out);
        return out;
    }

    private void place(int r, int n, int[] pos, boolean[] col, boolean[] d1, boolean[] d2, List<List<String>> out) {
        if (r == n) {                      // all rows filled: build the board
            List<String> board = new ArrayList<>();
            for (int c : pos) {
                char[] row = new char[n];
                Arrays.fill(row, '.');
                row[c] = 'Q';
                board.add(new String(row));
            }
            out.add(board);
            return;
        }
        for (int c = 0; c < n; c++) {
            if (col[c] || d1[r - c + n] || d2[r + c]) continue;   // attacked
            col[c] = d1[r - c + n] = d2[r + c] = true;
            pos[r] = c;
            place(r + 1, n, pos, col, d1, d2, out);
            col[c] = d1[r - c + n] = d2[r + c] = false;            // undo
        }
    }
}

