class Solution:
    def peacefulQueens(self, n: int) -> List[List[str]]:
        out, cols = [], []
        used_c, d1, d2 = set(), set(), set()
        def go(r):
            if r == n:
                out.append(["." * c + "Q" + "." * (n - c - 1) for c in cols]); return
            for c in range(n):
                if c in used_c or r - c in d1 or r + c in d2: continue
                used_c.add(c); d1.add(r - c); d2.add(r + c); cols.append(c)
                go(r + 1)
                used_c.remove(c); d1.remove(r - c); d2.remove(r + c); cols.pop()
        go(0)
        return out

