function peacefulQueens(n) {
  const out = [], pos = [];
  function safe(r, c) { for (let i = 0; i < r; i++) if (pos[i] === c || Math.abs(pos[i] - c) === r - i) return false; return true; }
  (function go(r) {
    if (r === n) { out.push(pos.map(c => ".".repeat(c) + "Q" + ".".repeat(n - c - 1))); return; }
    for (let c = 0; c < n; c++) if (safe(r, c)) { pos[r] = c; go(r + 1); }
  })(0);
  return out;
}
